<section id="unifiedReports" class="mkt-workspace"><div class="mkt-heading"><div><p class="eyebrow">ĐƠN HÀNG · QUẢNG CÁO · LỢI NHUẬN</p><h1>BÁO CÁO TỔNG HỢP</h1><p id="overviewStatus" role="status">Đang tải báo cáo…</p></div><button class="secondary" id="overviewRefresh">Làm mới</button></div>
<form id="mktFilters" class="overview-filters"><label>Thời gian<select name="period"></select></label><label>Từ ngày<input name="from" type="date"></label><label>Đến ngày<input name="to" type="date"></label><label>Mã sản phẩm<input name="sku" type="search" list="overviewSkuOptions" placeholder="Tất cả mã" autocomplete="off"><datalist id="overviewSkuOptions"></datalist></label><button class="primary">Áp dụng</button></form>
<div id="overviewNotice" class="mkt-alert" role="status"></div><div id="overviewMetrics" class="overview-cards"></div>
<details class="mkt-card"><summary>Doanh thu &amp; chi phí</summary><div class="mkt-table-wrap"><table class="overview-metrics"><thead><tr><th>Chỉ số</th><th>Tổng</th><th>Nam</th><th>Nữ</th></tr></thead><tbody id="overviewFinancials"></tbody></table></div></details><details class="mkt-card"><summary>Cách tính chỉ số</summary><p class="mkt-footnote">Đơn thực tế: số dòng đơn có sản phẩm theo ngày của sheet. Đã tạo: có nội dung cột Tạo đơn. Sản phẩm gửi đi: số chiếc đã tạo vận chuyển, không gồm HH; gồm cả hàng sau đó đã nhận hoặc hoàn. Chi phí/lượt mua = tổng quảng cáo ÷ lượt mua từ tiện ích. Chi phí/đơn thực tế = quảng cáo ÷ số đơn trong Bảng đơn.</p></details>
<details class="mkt-card" open><summary>Theo mã sản phẩm</summary><div class="mkt-table-wrap"><table><thead><tr><th>Mã</th><th>Đơn thực tế</th><th>Đã tạo</th><th>SP gửi đi</th><th>Quảng cáo</th><th>Lượt mua QC</th><th>CP/lượt mua</th><th>CP/đơn thực tế</th><th>Lỗ/Lãi</th></tr></thead><tbody id="overviewProducts"></tbody></table></div></details>
<details class="mkt-card"><summary>Theo chiến dịch / tài khoản</summary><div class="mkt-table-wrap"><table><thead><tr><th>Chiến dịch</th><th>Tài khoản</th><th>Quảng cáo</th><th>Lượt mua</th><th>CP/lượt mua</th></tr></thead><tbody id="overviewCampaigns"></tbody></table></div></details>
<details class="mkt-card"><summary>Lỗ / Lãi theo ngày</summary><div class="mkt-table-wrap"><table><thead><tr><th>Ngày</th><th>Doanh thu thành công</th><th>Quảng cáo</th><th>Giá vốn</th><th>Lỗ/Lãi</th></tr></thead><tbody id="overviewDaily"></tbody></table></div></details>
<details class="mkt-card"><summary>Giá cost / sản phẩm</summary><p class="hint">Giá có hiệu lực từ ngày đã chọn. Chưa có giá cost thì chưa tính lãi. Không nhập giá vốn bằng 0 để thay cho giá chưa biết.</p><form id="profitCost" class="mkt-import-fields"><label>Sản phẩm<select name="sku" required></select></label><label>Hiệu lực từ ngày<input name="effective" type="date" required></label><label>Cost / sản phẩm (VND)<input name="cost" type="number" min="0" step="1" required></label><label>Ghi chú<input name="note" maxlength="500"></label><button class="primary">Lưu giá cost</button></form><p id="profitCostStatus" role="status"></p><div id="profitCosts"></div></details><p id="overviewMethod" class="mkt-footnote"></p><details class="mkt-card"><summary>Lịch sử dữ liệu từ tiện ích</summary><div id="overviewSources"></div></details></section>
